package szserver;
import szserver.client.*;import szserver.net.*;import szserver.world.*;import java.util.*;import java.util.concurrent.*;import java.util.function.*;
/** Native scene UUID selection, separated entry/use triggers and delayed interaction identity. */
public final class PortalInteractionTests {
 private static int checks;private static void check(boolean ok,String name){checks++;if(!ok)throw new AssertionError(name);}
 private static NativePortal portal(UUID id,boolean use,double x,double target){return new NativePortal(id,"qa","teleport_generic",new World.Vec(x,64.9,8.5),1,new NativePortal.Parameters(use,1,false,false,1.5,List.of(new NativePortal.Destination(new World.Vec(target,64,8.5),1,"qa"))));}
 public static void main(String[] args)throws Exception{
  UUID a=new UUID(1,1),b=new UUID(1,2),bubble=new UUID(1,3);NativePortal door=portal(a,true,8.5,112.5),near=portal(b,true,10.5,144.5),automatic=portal(bubble,false,24.5,80.5);Map<UUID,NativePortal> portals=Map.of(a,door,b,near,bubble,automatic);World world=new World(new Terrain(){public boolean solid(int x,int y,int z){return false;}public Map<UUID,NativePortal> portalIndex(int x,int z){Map<UUID,NativePortal> out=new HashMap<>();for(var p:portals.values())if((int)Math.floor(p.position().x()/16)==x&&z==0)out.put(p.id(),p);return out;}});
  World.Vec source=new World.Vec(10,64,8.5);check(world.portal(source,false,null,0)==null,"walking into door does not activate");check(world.portal(source,true,a,0).portal().id().equals(a),"aimed UUID wins over nearer door");check(world.portal(source,true,b,0).target().x()==144.5,"other aimed door selects its own destination");check(world.portal(source,true,new UUID(4,5),0)==null,"unrelated UUID cannot activate nearest door");check(world.portal(new World.Vec(100,64,8.5),true,a,0)==null,"distant UUID rejected");check(world.portal(new World.Vec(24.5,64,8.5),false,null,0).portal().id().equals(bubble),"bubble activates on entry");check(world.portal(new World.Vec(24.5,64,8.5),true,bubble,0)==null,"F does not replace automatic bubble entry");
  Random random=new Random(42);for(int n=0;n<1000;n++){UUID id=new UUID(random.nextLong(),random.nextLong());byte[] body=Wire.bytes(out->{out.writeLong(id.getMostSignificantBits());out.writeLong(id.getLeastSignificantBits());});check(PortalPackets.interaction(body).equals(id),"UUID wire identity");}
  for(int n:new int[]{0,1,15,17,100}){try{PortalPackets.interaction(new byte[n]);throw new AssertionError("malformed use accepted");}catch(java.io.IOException expected){checks++;}}
  check(GameplayPacketAliases.registered(PortalPackets.INTERACT_CLASS)==1632,"native dynamic alias uses actual registered codec");
  check(GameplayPacketAliases.registered(PortalPackets.STATUS_CLASS)==180,"native availability alias");for(boolean enabled:new boolean[]{false,true}){byte[] frame=Wire.readFrame(new java.io.ByteArrayInputStream(PortalPackets.status(a,enabled)));var input=Wire.input(frame);check(input.readUnsignedByte()==5&&input.readUTF().equals(PortalPackets.STATUS_CLASS),"availability uses native named codec");byte[] body=input.readAllBytes();check(PortalPackets.status(body).equals(a)&&body[16]==(enabled?1:0),"availability reply preserves target and enabled flag");}
  byte[] compressed=com.github.luben.zstd.Zstd.compress(new byte[]{10,0,0,0});byte[] save=Wire.bytes(out->{out.writeLong(a.getMostSignificantBits());out.writeLong(a.getLeastSignificantBits());out.writeInt(compressed.length+5);out.writeInt(compressed.length);out.write(compressed);out.writeBoolean(false);});var settings=PortalPackets.settings(save);check(settings!=null&&settings.identity().equals(a)&&Arrays.equals(settings.compressed(),compressed),"portal DTO separated from anomaly DTO");check(PortalPackets.settings(new byte[40])==null,"unrelated typed DTO not guessed as portal");byte[] malformed=save.clone();malformed[19]++;try{PortalPackets.settings(malformed);throw new AssertionError("invalid portal envelope accepted");}catch(java.io.IOException expected){checks++;}
  PortalLookup lookup=new PortalLookup();List<PortalLookup.Request> requests=new ArrayList<>();List<CompletableFuture<World.PortalQuery>> futures=new ArrayList<>();Function<PortalLookup.Request,CompletableFuture<World.PortalQuery>> submit=r->{requests.add(r);var f=new CompletableFuture<World.PortalQuery>();futures.add(f);return f;};
  lookup.request(source,false,1,0,0,submit);lookup.request(source,true,1,.5,a,1,submit);futures.get(0).complete(new World.PortalQuery(null,true,0));lookup.advance(source,1,true,2,()->0,submit);check(a.equals(requests.get(1).objectId()),"queued F keeps aimed UUID behind entry lookup");futures.get(1).complete(world.portalQuery(source,true,a,.5));check(lookup.advance(source,1,true,3,()->0,submit).activation().portal().id().equals(a),"queued F activates selected door");
  lookup.request(source,true,1,.5,b,10,submit);futures.get(2).complete(new World.PortalQuery(null,true,0));lookup.advance(source,1,true,11,()->1,submit);lookup.advance(source,1,true,50_000_011,()->1,submit);check(b.equals(requests.get(3).objectId()),"scene generation retry keeps original selection");lookup.clear();
  System.out.println("PASS portal interaction "+checks+" checks");
 }
}
